@Component("employee-entity-projector")
public class EmployeeEntityProjector implements EntityProjector<Employee>{
		
	// core constructor
	public EmployeeEntityProjector(ProjectorRegistry registry,
										EmployeeRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Employee> getEntityClass() {
		return Employee.class;
	}

    /*
	 * Insert a Employee
	 * 
     * @param	entity Employee
     */
    public Employee create( Employee entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Employee
	 * 
     * @param	entity Employee
     */
    public Employee update( Employee entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Employee
	 * 
     * @param	id		UUID
     */
    public Employee delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Employee entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a WorkCenter
     * 
     * @param	parentId	UUID
     * @param	assignment 	WorkCenter 
     * @return	Employee
     */
    public Employee assignWorkCenter( UUID parentId, WorkCenter assignment ) {
	    LOGGER.info("assigning WorkCenter as " + assignment.toString() );

	    Employee parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( WorkCenter.class, assignment.getWorkCenterId());

	    // ------------------------------------------
		// assign the WorkCenter to the parent entity
		// ------------------------------------------ 
	    parentEntity.setWorkCenter( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the WorkCenter
	 * 
	 * @param	parentId		UUID
	 * @return	Employee
	 */
	public Employee unAssignWorkCenter( UUID parentId ) {
		Employee parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning WorkCenter on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the WorkCenter on the parent entithy
		// ------------------------------------------     
	    parentEntity.setWorkCenter(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the ShiftAssignments
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Employee
     */
    public Employee addToShiftAssignments( UUID parentId, ShiftAssignment addTo ) {
	    LOGGER.info("handling AssignShiftAssignmentsToEmployeeEvent - " );
	    
	    Employee parentEntity = repository.findById(parentId).get();
	    ShiftAssignment child = registry.project( ShiftAssignment.class, addTo.getShiftAssignmentId());
	    
	    parentEntity.getShiftAssignments().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the ShiftAssignments
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Employee
     */
	public Employee removeFromShiftAssignments( UUID parentId, ShiftAssignment removeFrom ) {
	    LOGGER.info("handling RemoveShiftAssignmentsFromEmployeeEvent " );
	
	    Employee parentEntity = repository.findById(parentId).get();
	    ShiftAssignment child = registry.project( ShiftAssignment.class, removeFrom.getShiftAssignmentId());
	    
	    parentEntity.getShiftAssignments().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

    /*
     * Add to the CorrectiveActions
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Employee
     */
    public Employee addToCorrectiveActions( UUID parentId, CorrectiveAction addTo ) {
	    LOGGER.info("handling AssignCorrectiveActionsToEmployeeEvent - " );
	    
	    Employee parentEntity = repository.findById(parentId).get();
	    CorrectiveAction child = registry.project( CorrectiveAction.class, addTo.getCorrectiveActionId());
	    
	    parentEntity.getCorrectiveActions().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the CorrectiveActions
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Employee
     */
	public Employee removeFromCorrectiveActions( UUID parentId, CorrectiveAction removeFrom ) {
	    LOGGER.info("handling RemoveCorrectiveActionsFromEmployeeEvent " );
	
	    Employee parentEntity = repository.findById(parentId).get();
	    CorrectiveAction child = registry.project( CorrectiveAction.class, removeFrom.getCorrectiveActionId());
	    
	    parentEntity.getCorrectiveActions().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Employee via an FindEmployeeQuery
     * @return 	query	FindEmployeeQuery
     */
    @SuppressWarnings("unused")
    public Employee find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Employee - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Employees
     *
     * @param	query	FindAllEmployeeQuery 
     * @return 	List<Employee> 
     */
    @SuppressWarnings("unused")
    public List<Employee> findAll( FindAllEmployeeQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Employee - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final EmployeeRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(EmployeeEntityProjector.class.getName());

}
